head.script:
let moduleData = [];
let chartInstances = {};

scwin.onpageload = function () {
    console.log("=== 모듈 대시보드 페이지 로드 ===");
    scwin.loadModuleData();
};

scwin.loadModuleData = function () {
    console.log("모듈 데이터 로드 시작");
    $p.executeSubmission("sbm_selectModuleList");
};

scwin.sbm_selectModuleList_submitdone = function (e) {
    console.log("=== 모듈 데이터 조회 성공 ===");
    console.log("서버 응답:", e);
    console.log("응답 텍스트:", e.responseText);

    try {
        let responseData = null;

        if (e.responseText) {
            responseData = JSON.parse(e.responseText);
            console.log("파싱된 응답 데이터:", responseData);
        }

        if (responseData && responseData.moduleVoList && responseData.moduleVoList.length > 0) {
            console.log(`DB에서 ${responseData.moduleVoList.length}개 모듈 데이터 로드 성공`);
            moduleData = responseData.moduleVoList;
        } else {
            console.error("DB 응답에서 moduleVoList를 찾을 수 없습니다.");
            scwin.showErrorMessage("모듈 데이터를 불러올 수 없습니다.");
            return;
        }

        scwin.populateDataList(moduleData);

        scwin.processModuleData();

    } catch (error) {
        console.error("모듈 데이터 처리 중 오류:", error);
        scwin.showErrorMessage("데이터 처리 중 오류가 발생했습니다.");
    }
};

scwin.sbm_selectModuleList_submiterror = function (e) {
    console.error("=== 모듈 데이터 조회 실패 ===");
    console.error("오류 상세:", e);
    console.error("오류 메시지:", e.message);
    console.error("HTTP 상태:", e.status);

    scwin.showErrorMessage("서버에서 데이터를 불러올 수 없습니다.");
};

scwin.populateDataList = function (moduleArray) {
    try {
        const moduleDataList = $p.getComponentById("dlt_moduleList");

        moduleDataList.removeAll();

        moduleArray.forEach(module => {
            const rowIndex = moduleDataList.insertRow();
            moduleDataList.setCellData(rowIndex, "moduleId", module.moduleId || '');
            moduleDataList.setCellData(rowIndex, "code", module.code || '');
            moduleDataList.setCellData(rowIndex, "name", module.name || '');
            moduleDataList.setCellData(rowIndex, "description", module.description || '');
            moduleDataList.setCellData(rowIndex, "price", module.price || '0.00');
            moduleDataList.setCellData(rowIndex, "icon", module.icon || '');

            const category = scwin.getCategoryFromCode(module.code);
            const priceRange = scwin.getPriceRange(parseFloat(module.price));
            moduleDataList.setCellData(rowIndex, "category", category);
            moduleDataList.setCellData(rowIndex, "priceRange", priceRange);
        });

        console.log(`DataList에 ${moduleArray.length}개 모듈 데이터 추가 완료`);

    } catch (error) {
        console.error("DataList 데이터 추가 오류:", error);
    }
};

scwin.processModuleData = function () {
    console.log("모듈 데이터 분석 시작:", moduleData);

    if (!moduleData || moduleData.length === 0) {
        console.error("처리할 모듈 데이터가 없습니다.");
        scwin.showErrorMessage("모듈 데이터가 없습니다.");
        return;
    }

    moduleData.forEach(module => {
        if (!module.category) {
            module.category = scwin.getCategoryFromCode(module.code);
        }
        if (!module.priceRange) {
            module.priceRange = scwin.getPriceRange(parseFloat(module.price));
        }
    });

    const stats = scwin.calculateDashboardStats();
    console.log("계산된 통계:", stats);

    scwin.updateDashboardUI(stats);

    setTimeout(() => {
        scwin.createCharts();
    }, 500);
};

scwin.getCategoryFromCode = function (code) {
    const categoryMap = {
        'CHAT': '커뮤니케이션',
        'VIDEO': '미디어',
        'CANVAS': '교육도구',
        'QUIZ': '교육도구',
        'FACEAI': 'AI 도구',
        'PARTICIPANTS': '관리도구',
        'ABSENT': '관리도구',
        'SCREEN': '미디어',
        'MIC': '미디어',
        'CAMERA': '미디어',
        'ATTENDANCE': '관리도구'
    };
    return categoryMap[code] || '기타';
};

scwin.getPriceRange = function (price) {
    if (price === 0) return '무료';
    if (price < 10000) return '1만원 미만';
    if (price < 50000) return '1-5만원';
    if (price < 100000) return '5-10만원';
    if (price < 200000) return '10-20만원';
    return '20만원 이상';
};

scwin.calculateDashboardStats = function () {
    const totalModules = moduleData.length;
    const freeModules = moduleData.filter(m => parseFloat(m.price) === 0).length;
    const paidModules = totalModules - freeModules;
    const totalRevenue = moduleData.reduce((sum, m) => sum + parseFloat(m.price), 0);
    const avgPrice = paidModules > 0 ? totalRevenue / paidModules : 0;
    const highPriceModules = moduleData.filter(m => parseFloat(m.price) > 100000).length;

    return {
        totalModules,
        freeModules,
        paidModules,
        avgPrice: Math.round(avgPrice),
        totalRevenue: Math.round(totalRevenue),
        highPriceModules
    };
};

scwin.updateDashboardUI = function (stats) {
    try {
        setTimeout(() => {
            const statCards = document.querySelectorAll('.stat-number');
            if (statCards.length >= 6) {
                statCards[0].textContent = stats.totalModules;
                statCards[1].textContent = stats.freeModules;
                statCards[2].textContent = stats.paidModules;
                statCards[3].textContent = `₩${stats.avgPrice.toLocaleString()}`;
                statCards[4].textContent = `₩${stats.totalRevenue.toLocaleString()}`;
                statCards[5].textContent = stats.highPriceModules;
            }

            scwin.updateTopModules();

            console.log("대시보드 UI 업데이트 완료");
        }, 100);
    } catch (error) {
        console.error("대시보드 UI 업데이트 오류:", error);
    }
};

scwin.updateTopModules = function () {
    try {
        const sortedModules = [...moduleData]
            .sort((a, b) => parseFloat(b.price) - parseFloat(a.price))
            .slice(0, 5);

        const topModulesContainer = document.querySelector('.top-modules-list');
        if (topModulesContainer) {
            topModulesContainer.innerHTML = '';

            sortedModules.forEach((module, index) => {
                const moduleItem = document.createElement('div');
                moduleItem.className = 'top-module-item';
                moduleItem.innerHTML = `
                    <div class="module-rank">#${index + 1}</div>
                    <div class="module-icon-small">${module.icon}</div>
                    <div class="module-info-small">
                        <div class="module-name-small">${module.name}</div>
                        <div class="module-category-small">${module.category}</div>
                    </div>
                    <div class="module-price-small">₩${parseInt(module.price).toLocaleString()}</div>
                `;
                topModulesContainer.appendChild(moduleItem);
            });
        }
    } catch (error) {
        console.error("TOP 모듈 업데이트 오류:", error);
    }
};

scwin.createCharts = function () {
    scwin.createPriceDistributionChart();
    scwin.createCategoryChart();
};

scwin.createPriceDistributionChart = function () {
    try {
        const canvas = document.getElementById('priceChart');
        if (!canvas) {
            console.warn("priceChart 캔버스를 찾을 수 없습니다.");
            return;
        }

        const ctx = canvas.getContext('2d');

        if (chartInstances.priceChart) {
            chartInstances.priceChart.destroy();
        }

        const priceRanges = {};
        moduleData.forEach(module => {
            const range = module.priceRange || scwin.getPriceRange(parseFloat(module.price));
            priceRanges[range] = (priceRanges[range] || 0) + 1;
        });

        const labels = Object.keys(priceRanges);
        const data = Object.values(priceRanges);
        const colors = ['#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4', '#feca57', '#ff9ff3'];

        chartInstances.priceChart = new Chart(ctx, {
            type: 'doughnut',
            data: {
                labels: labels,
                datasets: [{
                    data: data,
                    backgroundColor: colors.slice(0, labels.length),
                    borderWidth: 2,
                    borderColor: '#fff'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: {
                            padding: 15,
                            usePointStyle: true,
                            font: { size: 11 }
                        }
                    },
                    tooltip: {
                        callbacks: {
                            label: function (context) {
                                const total = context.dataset.data.reduce((a, b) => a + b, 0);
                                const percentage = ((context.parsed * 100) / total).toFixed(1);
                                return `${context.label}: ${context.parsed}개 (${percentage}%)`;
                            }
                        }
                    }
                }
            }
        });

        console.log("가격 분포 차트 생성 완료");
    } catch (error) {
        console.error("가격 분포 차트 생성 오류:", error);
    }
};

scwin.createCategoryChart = function () {
    try {
        const canvas = document.getElementById('categoryChart');
        if (!canvas) {
            console.warn("categoryChart 캔버스를 찾을 수 없습니다.");
            return;
        }

        const ctx = canvas.getContext('2d');

        if (chartInstances.categoryChart) {
            chartInstances.categoryChart.destroy();
        }

        const categories = {};
        moduleData.forEach(module => {
            const category = module.category || scwin.getCategoryFromCode(module.code);
            categories[category] = (categories[category] || 0) + 1;
        });

        const labels = Object.keys(categories);
        const data = Object.values(categories);

        chartInstances.categoryChart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [{
                    label: '모듈 수',
                    data: data,
                    backgroundColor: [
                        '#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4',
                        '#feca57', '#ff9ff3', '#a8e6cf', '#dda0dd'
                    ],
                    borderColor: [
                        '#e55656', '#3fb8af', '#3a9bc8', '#7fb069',
                        '#feb941', '#ff85e6', '#86d3a0', '#c285c2'
                    ],
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true,
                        ticks: {
                            stepSize: 1,
                            font: { size: 11 }
                        }
                    },
                    x: {
                        ticks: {
                            font: { size: 10 },
                            maxRotation: 45
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: false
                    },
                    tooltip: {
                        callbacks: {
                            label: function (context) {
                                return `${context.label}: ${context.parsed.y}개`;
                            }
                        }
                    }
                }
            }
        });

        console.log("카테고리 차트 생성 완료");
    } catch (error) {
        console.error("카테고리 차트 생성 오류:", error);
    }
};

scwin.showErrorMessage = function (message) {
    try {
        setTimeout(() => {
            const statNumbers = document.querySelectorAll('.stat-number');
            if (statNumbers.length >= 6) {
                statNumbers[0].textContent = '0';
                statNumbers[1].textContent = '0';
                statNumbers[2].textContent = '0';
                statNumbers[3].textContent = '₩0';
                statNumbers[4].textContent = '₩0';
                statNumbers[5].textContent = '0';
            }
        }, 100);

        const chartContainers = document.querySelectorAll('.chart-container');
        chartContainers.forEach(container => {
            container.innerHTML = `
                <div class="error-message">
                    <div class="error-icon">⚠️</div>
                    <div class="error-text">${message}</div>
                    <button class="retry-btn" onclick="scwin.loadModuleData()">다시 시도</button>
                </div>
            `;
        });

        const topModulesContainer = document.querySelector('.top-modules-list');
        if (topModulesContainer) {
            topModulesContainer.innerHTML = `
                <div class="error-message">
                    <div class="error-icon">⚠️</div>
                    <div class="error-text">${message}</div>
                </div>
            `;
        }

        console.error("에러 메시지 표시:", message);
    } catch (error) {
        console.error("에러 메시지 표시 중 오류:", error);
    }
};

scwin.btn_home_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_dashboard.xml";
};

scwin.btn_tenant_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_tenant.xml";
};

scwin.btn_module_onclick = function () {
    console.log("현재 모듈 분석 페이지입니다.");
};

scwin.btn_stats_onclick = function () {
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/mobile_dev_server_info.xml";
};

scwin.refreshData = function () {
    console.log("데이터 새로고침");
    scwin.loadModuleData();
};
